create extension if not exists pgcrypto;
create table admin_users (id uuid primary key default gen_random_uuid(), auth_user_id uuid not null unique, email varchar(320) not null unique, role varchar(30) not null check(role='ADMIN'), is_active boolean not null default true, created_at timestamptz not null default now());
create table stores (id uuid primary key default gen_random_uuid(), name varchar(100) not null, slug varchar(120) not null unique, logo_url text, is_active boolean not null default true, created_at timestamptz not null default now());
create table categories (id uuid primary key default gen_random_uuid(), name varchar(100) not null, slug varchar(120) not null unique, display_order integer not null default 0, is_active boolean not null default true);
create table products (id uuid primary key default gen_random_uuid(), slug varchar(160) not null unique, name varchar(160) not null, description text not null, store_id uuid not null references stores(id), outbound_url text not null, current_price numeric(12,2) not null check(current_price>=0), original_price numeric(12,2), image_url text, status varchar(20) not null check(status in ('DRAFT','ACTIVE','ARCHIVED')), expires_at timestamptz, version integer not null default 0, created_at timestamptz not null default now(), check(original_price is null or original_price > current_price));
create table product_categories (product_id uuid not null references products(id) on delete cascade, category_id uuid not null references categories(id), primary key(product_id,category_id));
create table price_ranges (id uuid primary key default gen_random_uuid(), label varchar(80) not null, min_price numeric(12,2) not null check(min_price >= 0), max_price numeric(12,2), display_order integer not null default 0, check(max_price is null or min_price <= max_price));
create table best_item_placements (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, category_id uuid not null references categories(id), price_range_id uuid references price_ranges(id), rank integer not null check(rank>0), version integer not null default 0, unique(category_id,price_range_id,rank), unique(product_id,category_id,price_range_id));
create table explore_products (product_id uuid primary key references products(id) on delete cascade, display_order integer not null default 0, is_visible boolean not null default true);
create table site_content (content_key varchar(80) primary key, content_json jsonb not null default '{}'::jsonb, version integer not null default 0, updated_at timestamptz not null default now());
create table outbound_clicks (id bigserial primary key, product_id uuid not null references products(id), created_at timestamptz not null);
create table product_suggestions (id uuid primary key default gen_random_uuid(), name varchar(160) not null, url text, note varchar(1000), contact varchar(320), status varchar(20) not null check(status in ('NEW','REJECTED','CONVERTED')), created_at timestamptz not null);
create table audit_logs (id bigserial primary key, actor_id uuid references admin_users(id), action varchar(100) not null, entity_type varchar(80) not null, entity_id uuid, before_json jsonb, after_json jsonb, created_at timestamptz not null default now());
create index products_active_created_idx on products(status,created_at desc);
create index product_suggestions_status_created_idx on product_suggestions(status,created_at desc);
